    ax.set_yticks(y); ax.set_yticklabels([r[0] for r in ROWS], fontsize=8.5); ax.set_xlim(0, max(v) * 1.15); ax.set_xlabel("MAE 00:00-06:00, ct/kWh"); ax.grid(True, axis="x", color=GRID, linewidth=0.6); ax.set_axisbelow(True); [ax.spines[s].set_visible(False) for s in ("top", "right")]
    ax.set_title(f"{per}: best {best:.2f} ct ({ROWS[int(np.argmin(v))][0].split(':')[0].split(',')[0]})", loc="left", fontsize=9.5, fontweight="bold", color=INK)
